<?php
$base=site_url('cartella-clinica/pazienti/'.$patientId.'/pacs');
$search=$search ?? null; $details=$details ?? null;
$date=static fn(string $v): string => preg_match('/^[0-9]{8}$/D',$v) ? substr($v,6,2).'/'.substr($v,4,2).'/'.substr($v,0,4) : ($v ?: 'Non indicata');
$name=static fn(string $v): string => trim(str_replace('^',' ',$v));
$localTime=static fn(string $v): string => (new \DateTimeImmutable($v,new \DateTimeZone('UTC')))->setTimezone(new \DateTimeZone('Europe/Rome'))->format('d/m/Y H:i');
?>
<!doctype html>
<html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>Esami e immagini | AmbulatorioFacile</title>
<style>
:root{color-scheme:light;--ink:#193345;--muted:#576c78;--brand:#086f75;--line:#dce5e9}*{box-sizing:border-box}body{margin:0;background:#f3f6f8;color:var(--ink);font:15px/1.55 system-ui,sans-serif}header,main{max-width:1160px;margin:auto;padding:24px}header{padding-bottom:0}h1{margin:10px 0}h2{font-size:22px}h3{font-size:17px}a{color:var(--brand)}.card{background:white;border:1px solid var(--line);border-radius:12px;padding:24px;margin:0 0 20px}.muted,small{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.row{border-top:1px solid var(--line);padding:18px 0;overflow-wrap:anywhere}.actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}label{display:block;font-weight:600}input,select{width:100%;padding:10px;margin:6px 0 12px;border:1px solid #afc2ca;border-radius:6px;font:inherit}input[type=checkbox]{width:auto}button,.button{display:inline-block;padding:10px 16px;background:var(--brand);color:white;border:0;border-radius:6px;font:600 14px system-ui;text-decoration:none;cursor:pointer}.secondary{background:#e8f2f3;color:#145b61}.notice{padding:16px;border-left:4px solid var(--brand);background:#e5f4ef;margin-bottom:20px}summary{cursor:pointer;font-weight:600}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #e69f35;outline-offset:3px}.uid{font-size:12px;word-break:break-all}.full{grid-column:1/-1}@media(max-width:650px){.grid{grid-template-columns:1fr}header,main{padding:16px}.card{padding:18px}}
